const { S3Client, GetObjectCommand } = require("@aws-sdk/client-s3");
const { CloudWatchClient, GetMetricDataCommand } = require("@aws-sdk/client-cloudwatch");
(async () => {
  const endpoint = process.env.AWS_ENDPOINT_URL;
  const s3 = new S3Client({ endpoint, region: 'us-east-1', forcePathStyle: true });
  const cw = new CloudWatchClient({ endpoint, region: 'us-east-1' });
  async function getCat(bucket, key){
    const res = await s3.send(new GetObjectCommand({Bucket: bucket, Key: key}));
    const body = await res.Body.transformToString();
    console.log("===CAT", key, "===\n", JSON.stringify(JSON.parse(body), null, 2));
    return JSON.parse(body);
  }
  const cats = [
    ["meteringco-billing-sandbox","catalogues/biz-ridge-2026-07.json"],
    ["meteringco-billing-sandbox","catalogues/biz-vale-2026-07.json"]
  ];
  for (const [b,k] of cats){
    const cat = await getCat(b,k);
    console.log("\n--- Metrics for", cat.businessID, "---");
    for (const enrol of cat.enrolments){
      const off = cat.offerings.find(o=>o.offeringId===enrol.offeringId);
      console.log(`\nCustomer ${enrol.customerId} offering ${off.offeringName}`);
      for (const dim of off.dimensions){
        const dims = { BusinessId: cat.businessID, CustomerId: enrol.customerId, DimensionId: dim.dimensionId };
        const startTime = new Date(cat.periodStart);
        const endTime = new Date(cat.periodEnd);
        const period = cat.usagePeriod;
        // use helper similar to cloudwatch.ts
        const readings = [];
        let NextToken;
        do {
          const resp = await cw.send(new GetMetricDataCommand({
            StartTime: startTime,
            EndTime: endTime,
            ScanBy: 'TimestampAscending',
            NextToken,
            MetricDataQueries: [{
              Id: 'series',
              ReturnData: true,
              MetricStat: {
                Metric: { Namespace: cat.usageNamespace, MetricName: cat.usageMetricName, Dimensions: Object.keys(dims).map(Name=>({Name, Value:dims[Name]}))},
                Period: period,
                Stat: 'Sum',
              }
            }]
          }));
          (resp.MetricDataResults||[]).forEach(mdr=>{
            (mdr.Values||[]).forEach((v,i)=> {
              const ts = mdr.Timestamps[i];
              readings.push({ timestamp: new Date(ts).toISOString(), value: Number(v) });
            });
          });
          NextToken = resp.NextToken;
        } while(NextToken);
        readings.sort((a,b)=>a.timestamp.localeCompare(b.timestamp));
        console.log(`  dim ${dim.dimensionId} (${dim.dimensionName}) price ${dim.consumptionPrice} entitlement ${dim.usageEntitlement} overage ${dim.overageAllowed}`);
        console.log(`    readings: ${JSON.stringify(readings)} sum=${readings.reduce((a,c)=>a+c.value,0)}`);
      }
    }
  }
})();
