async function getCatalog(endpoint, bucket, key){
  const s3 = new S3Client({ endpoint, region: 'us-east-1', forcePathStyle: true });
  const res = await s3.send(new GetObjectCommand({Bucket: bucket, Key: key}));
  return JSON.parse(await res.Body.transformToString());
}

async function getMetricSum(endpoint, cat, customerId, dimId){
  const cw = new CloudWatchClient({ endpoint, region: 'us-east-1'});
  const dims = { BusinessId: cat.businessID, CustomerId: customerId, DimensionId: dimId };
  let readings=[];
  let NextToken;
  do{
    const resp = await cw.send(new GetMetricDataCommand({
      StartTime: new Date(cat.periodStart),
      EndTime: new Date(cat.periodEnd),
      ScanBy: 'TimestampAscending',
      NextToken,
      MetricDataQueries: [{ Id:'series', ReturnData:true, MetricStat:{ Metric:{Namespace:cat.usageNamespace, MetricName:cat.usageMetricName, Dimensions:Object.keys(dims).map(Name=>({Name,Value:dims[Name]}))}, Period:cat.usagePeriod, Stat:'Sum'}}]
    }));
    (resp.MetricDataResults||[]).forEach(mdr=>{
      (mdr.Values||[]).forEach(v=>readings.push(Number(v)));
    });
    NextToken=resp.NextToken;
  }while(NextToken);
  return readings.reduce((a,b)=>a+b,0);
}

