process.env.AWS_ENDPOINT_URL = process.env.AWS_ENDPOINT_URL || 'http://127.0.0.1:4566';
process.env.AWS_REGION = 'us-east-1';
import { InvoiceLineGathererService } from './src/microservices/invoiceLineGatherer/invoiceLineGatherer.service.js';

async function test(){
  const svc = new InvoiceLineGathererService();
  const ridge = await svc.gatherInvoiceLines({ businessID: 'biz-ridge', catalogueBucket: 'meteringco-billing-sandbox', catalogueKey: 'catalogues/biz-ridge-2026-07.json' });
  const vale = await svc.gatherInvoiceLines({ businessID: 'biz-vale', catalogueBucket: 'meteringco-billing-sandbox', catalogueKey: 'catalogues/biz-vale-2026-07.json' });
  console.log("RIDGE:", JSON.stringify(ridge, null,2));
  console.log("VALE:", JSON.stringify(vale, null,2));

  // Expected checks
  const ridgeAlpha = ridge.find(c=>c.customerId==='cus_sample_alpha')!;
  const ridgeBravo = ridge.find(c=>c.customerId==='cus_sample_bravo')!;
  const valeCharlie = vale.find(c=>c.customerId==='cus_sample_charlie')!;

  function assert(cond: boolean, msg:string){ if(!cond){ throw new Error("ASSERT FAIL: "+msg); } console.log("PASS: "+msg); }

  // ridge alpha: api-calls 100 at 0.01, seats 2 at 10, nothing else
  assert(ridgeAlpha.lineItems.length===2, "ridge alpha 2 lines (hide free)");
  const api = ridgeAlpha.lineItems.find(l=>l.name.includes('Ridge API Calls'));
  assert(!!api && api.quantity===100 && api.unitCost===0.01, "api calls 100");
  const seats = ridgeAlpha.lineItems.find(l=>l.name.includes('Ridge Seats'));
  assert(!!seats && seats.quantity===2 && seats.unitCost===10, "seats 2 (12-10)");
  assert(!ridgeAlpha.lineItems.find(l=>l.name.includes('Ridge Alerts')), "alerts hidden (price 0 hide)");
  assert(!ridgeAlpha.lineItems.find(l=>l.name.includes('Ridge Reports')), "reports not exhausted overage false -> no line");
  assert(!ridgeAlpha.lineItems.find(l=>l.name.includes('Ridge Storage')), "storage inf -> no line");

  // ridge bravo: jobs 200, minutes 80 but entitlement 100 not exhausted => no line, scans inf => no, tasks 50 overage false 70 -> no
  assert(ridgeBravo.lineItems.length===1, "ridge bravo 1 line");
  const jobs = ridgeBravo.lineItems.find(l=>l.name.includes('Ridge Jobs'));
  assert(!!jobs && jobs.quantity===200, "jobs 200");
  assert(!ridgeBravo.lineItems.find(l=>l.name.includes('Ridge Minutes')), "minutes not exhausted");
  assert(!ridgeBravo.lineItems.find(l=>l.name.includes('Ridge Scans')), "scans inf no line");
  assert(!ridgeBravo.lineItems.find(l=>l.name.includes('Ridge Tasks')), "tasks overage forbidden");

  // vale charlie: messages 50, hours 10 (price 0 show), units 5 (25-20)
  assert(valeCharlie.lineItems.length===3, "vale 3 lines (show free)");
  const msgs = valeCharlie.lineItems.find(l=>l.name.includes('Vale Messages'));
  assert(!!msgs && msgs.quantity===50, "vale messages 50");
  const hours = valeCharlie.lineItems.find(l=>l.name.includes('Vale Hours'));
  assert(!!hours && hours.quantity===10 && hours.unitCost===0, "vale hours 10 price 0 show");
  const units = valeCharlie.lineItems.find(l=>l.name.includes('Vale Units'));
  assert(!!units && units.quantity===5, "vale units 5 (25-20)");

  console.log("ALL CHECKS PASSED");
}
test().catch(e=>{ console.error(e); process.exit(1); });
EOF
