                    owed = totalNum;
                }

                const priceStr = (dimension as any).consumptionPrice;
                const priceZero = priceStr !== undefined && priceStr !== null && parseFloat(priceStr) === 0;
                const hideFree = catalogue.settings?.freeDimensionOnInvoice === 'hide';

                // Line if owed>0, or if zero-priced and not hidden (free line)
                // Owed takes precedence so a zero-price dimension that is owed still shows even when hide is true
                let include = false;
                if (owed > 0) {
